"""
Generate docs/DATA.md from the column comments in schema.sql.

  python -m garmin_sync.docs           # rewrite docs/DATA.md
  python -m garmin_sync.docs --check   # exit 1 if it is out of date (CI)
"""

import argparse
import sys

import duckdb

from garmin_sync.config import ROOT
from garmin_sync.db import init_schema

OUT = ROOT / "docs" / "DATA.md"

HEADER = """\
# Data dictionary

<!-- Generated by `python -m garmin_sync.docs` from the comments in garmin_sync/schema.sql. Do not edit by hand. -->

The same descriptions are served to the model by the MCP `describe_schema` tool, together with
live fill rates, so the docs a human reads and the docs the model reads cannot drift apart.
"""


def render() -> str:
    con = duckdb.connect()
    init_schema(con)
    parts = [HEADER]
    for table, comment in con.execute(
        "SELECT table_name, comment FROM duckdb_tables() ORDER BY table_name DESC"
    ).fetchall():
        parts.append(f"\n## `{table}`\n\n{comment}\n\n| Column | Type | Meaning |\n|---|---|---|")
        for name, dtype, col_comment in con.execute(
            "SELECT column_name, data_type, comment FROM duckdb_columns() WHERE table_name = ? ORDER BY column_index",
            [table],
        ).fetchall():
            parts.append(f"| `{name}` | {dtype} | {(col_comment or '').replace('|', '/')} |")
    return "\n".join(parts) + "\n"


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    text = render()
    if args.check:
        if not OUT.exists() or OUT.read_text() != text:
            print("docs/DATA.md is stale. Run: python -m garmin_sync.docs")
            sys.exit(1)
        print("docs/DATA.md is up to date")
    else:
        OUT.write_text(text)
        print(f"Wrote {OUT}")
